    "purpose": "600 yıllık Divan Edebiyatı geleneğine, modern yaklaşımlarla çözümleme teknikleri üretmek; Eski Edebiyatın gövdesini oluşturan klasik şiirimizin felsefi arka planını ve özelliklerini öğreterek öğrencinin sahaya nüfuz etmesini sağlamaktır.",
    "content": "Modern edebiyat teorilerine ait özelliklerden yola çıkılarak; bu teorilerle klasik Türk edebiyatı eserleri arasında ilişki kurulacak ve eserlerin incelemesi yapılacaktır. Tarihsel yaklaşım, psikolojik yaklaşım, metinbilimsel yaklaşım, dilbilimsel yaklaşım, ontolojik analiz metodu hakkında örnek çalışma ve metinlerden hareketle bilgi verilip, uygulama yapılacaktır. Bu amaçla, modern teorilerle geleneğin ilişkisini araştıran kitap ve yazılar gözden geçirilecektir. Klasik Türk edebiyatı sahasında yapılan araştırmalarda farklı disiplinlerin yöntemlerinden yararlanmak, araştırmacı adaylarını bu tür çalışmalardan haberdar etmek ve çalışmalarında yararlanmalarını sağlamak bu dersin amaçları arasındadır.",
    "methods": "Kuramsal anlatım, metin çözümlemesi, karşılaştırmalı dil ve edebiyat incelemesi ile akademik tartışma.",
    "resources": "Dersin gerçek OBS kaynakları; birincil edebî metinler, güncel Türk dili ve edebiyatı araştırmaları, kütüphane katalogları ve hakemli makaleler.",
    "sdgs": [
      "4",
      "11",
      "16"
    ],
    "outcomes": [
      "Modern teorilerin ışığında eski türk edebiyatı 1 kapsamındaki ileri kuramsal bilgileri analiz eder.",
      "Tarihî Türk dili yaklaşımlarını karşılaştırır.",
      "Modern teorilerin ışığında eski türk edebiyatı 1 kapsamında uygun Türk dili ve edebiyatı araştırma yöntemini uygular.",
      "Modern teorilerin ışığında eski türk edebiyatı 1 bulgularını dilsel, edebî ve toplumsal bağlamıyla değerlendirir.",
      "Modern teorilerin ışığında eski türk edebiyatı 1 alanındaki kanıtlara dayalı dilsel ve edebî argüman geliştirir."
    ],
    "weeklyTopics": [
      "Dersin ve ders kaynaklarının tanıtılması, beklentiler…",
      "Divan edebiyatı tarihi neden ve nasıl yazıl(ama)dı?",
      "Klasik edebiyatta kanon ve patronaj şiir üretim-tüketim ilişkileri",
      "Klasik şiirde telif-tercüme ve özgünlük meselesi",
      "Klasik edebiyatın felsefi, tarihsel arka planı",
      "“Mesnevî” türünün doğası, Aşk mesnevîleri, Roman-s ile ilişkilendirme",
      "Divan edebiyatında “aşk, âşık, sevgili ve sevme biçimleri” / Şiirde “Ben”lik",
      "Divan şiiri ve Toplumsal Cinsiyet Erkek-lik-ler, Kadın şairler",
      "Mekân algısının değişimi kahve/meyhane kültürü ve divan şiiri “Gazel” türünün toplumsal boyutu ve başka sosyo-kültürel okumaların mümkün kılınması",
      "Divan şiirinde İslâm Mistisizmi tasavvuf şiirinde poetik tartışmalar",
      "Divan şiirinde Mitoloji ütopik ve/ya gerçekçi algılar",
      "Divan edebiyatında Mensur türler ve dönüşüm",
      "Divan şiirinde Tipler rind, zâhid ve diğerleri",
      "Modern teorilerin isiginda eski turk edebiyati 1: ileri filolojik ve kuramsal incelemeler (14)",
      "Modern teorilerin ışığında eski türk edebiyatı 1: kapsam ve temel kavramlar"
    ],
