    "content": "Çocuk edebiyatı; alanın temel kavramları, tarihsel ve kültürel bağlam, birincil ve ikincil kaynaklar, metin çözümleme yöntemleri, tür ve biçim özellikleri, dil ve üslup incelemesi, karşılaştırmalı değerlendirme, güncel akademik tartışmalar boyutlarıyla ele alınır.",
