    "content": "Tür kavramının tanımı yapılacak, kapsamı ve çerçevesi belirtilecek. Klasik Türk edebiyatında ortaya çıkan türlere genel bir bakışın ardından Allah ile ilgili türler (esmâ-i hüsnâ, tevhid ve münâcât), Hz. Peygamber ile ilgili türler (hilye, kırk hadis ve gül-i sad-berg, mevlid, mirâciye, na’t ve siyer), dinî günler ve bayramları anlatan türler (ıydiye, ramazaniye ve regâ’ibiye), ahlakî yönü ön planda olan türler (nasihatnâme/pendnâme), asıl konuları din dışı olan türler yani bir yeri ya da yerleşim yerlerini anlatan türler (beldenâme/bilâdiye, dâriye, hammâmiye/hamâmnâme, sâhilnâme, sefâretnâme, seyâhatnâme ve şehrengiz) üzerinde durulacaktır. Bu edebî türlerin Türk edebiyat tarihinde hangi dönemlerde daha çok rağbet gördüğü şairler üzerinden izah edilecektir.",
