    "content": "Klasik Türk edebiyatında 17. yüzyıl başlarından itibaren görülmeye başlanan üslûptaki değişme ve çeşitlenmeler ele alınacak; Sebk-i Hindî’nin kuramsal çerçevesi, tarihsel gelişimi ve özellikleri ortaya konacak; Sebk-i Hindî’nin Türk edebiyatındaki önemli temsilcilerinin eserleri üslûp bakımından incelenecektir. Sebk-i Hindî’nin şairler üzerinde etkisin göstermeye başladığı 17. yüzyılda Nâbî’nin öncülüğünü yaptığı hikemî tarzla mukayesesi yapılarak ortak ve farklı yönleri üzerinden çeşitli değerlendirmelerde bulunulacaktır. Şairlerin bu akımı tercih etmelerine sebep olan âmiller irdelenerek bunların şairlerin ruh dünyasındaki etkilerinin manzumelere yansıması ortaya konulacaktır.",
