    "purpose": "Türkiye türkçesinin fonetik, morfolojik ve sentaktik özellikleri ıı alanındaki kaynakları, metinleri ve kuramsal yaklaşımları doktora düzeyinde eleştirel değerlendirme ve özgün araştırma yetkinliği kazandırmayı amaçlamaktadır.",
    "content": "Türkiye türkçesinin fonetik, morfolojik ve sentaktik özellikleri ıı; temel dilbilim kavramları, ses ve biçim yapıları, söz dizimi, anlam ilişkileri, söylem ve bağlam, gösterge ve anlatı yapıları, ağız ve varyasyon incelemesi, dil verilerinin çözümlenmesi boyutlarıyla ele alınır.",
