    "content": "Klasik Türk Edebiyatında Türler-I” olan dersin devamı olup tür kavramının tanımı, kapsamı ve çerçevesi özetlenecek. Klasik Türk edebiyatında ortaya çıkan türlere genel bir bakışın ardından eleştiri, şikâyet veya alay ve şaka içeren türler (hasb-i hâl, hezel, hiciv/hicviye ve latîfe), mevsimleri anlatan türler (bahâriye, sayfiye ve şitâiye), otobiyografi veya biyografiye dayalı türler (sergüzeştnâme, tezkire ve vefeyâtnâme), ölümü anlatan türler (maktel-i Hüseyin ve mersiye), övgü veya tebrik içeren türler (fahriye medhiye, rahşiye ve sıhhatnâme), savaşları, fetihleri ve zaferleri anlatan türler (fethiye/fetihnâme/zafernâme, gazavatnâme ve Selimnâme), sosyal hayatı konu alan türler (kahvenâme, sâkînâme ve sûrnâme) ve tahmin ve yorum içeren türler (fâlnâme ve kıyafetnâme) üzerinde durulacak.",
